    # RP-407: a cross-subject CL citation sends governing back to the original entry for the line's own subject.
    if cited_entry in cl_subjects and cl_subjects[cited_entry] != subject and subject in original:
        return original[subject]
    # RP-401 / RP-403.
    if subject in clarification:
        return clarification[subject]
    if subject in original:
        return original[subject]
    return 'NONE'

def addressee_father_ok(w):
    return (('father' in w or 'mr adler' in w or 'adam' in w) and
            ('attorney' in w or 'counsel' in w) and
            not ('mother' in w or 'ms corwin' in w or 'catherine' in w))

def addressee_mother_ok(w):
    return (('mother' in w or 'ms corwin' in w or 'catherine' in w) and
            ('attorney' in w or 'counsel' in w) and
            not ('father' in w or 'mr adler' in w or 'adam' in w))

def rofr_ok(w):
    return (('agreed' in w or 'agreement' in w) and
            ('mr adler' in w or 'father' in w) and
            ('overnight' in w or 'not to be left' in w) and
            ('without him' in w or 'without mr adler' in w or 'without the father' in w) and
            'mother' not in w and 'ms corwin' not in w and 'her present' not in w and
            'permitted' not in w)

def children_named_ok(w):
    return 'noor' in w and 'imogen' in w and 'seven' in w and 'twelve' in w

def overnight_stays_ok(w):
    return ('several' in w and 'both' in w and 'overnight' in w and
            'home' in w and 'sitter' in w and 'away' in w)

def inconsistent_accounts_ok(w):
    return ('wife' in w and 'school' in w and 'clinician' in w and
            ('sitter' in w or 'babysitter' in w) and 'me' in w and
            ('neighbour' in w or 'neighbor' in w))

def concern_old_ok(w):
    return ('concern' in w and
            ('appreciate' in w or 'violate' in w or 'contravene' in w) and
            'position' in w and ('put in' in w or 'placed in' in w))

def concern_new_ok(w):
    return ('concern' in w and 'position' in w and ('put in' in w or 'placed in' in w) and
            'appreciate' not in w and 'violate' not in w and 'contravene' not in w)

def behavioural_plan_old_ok(w):
    return ('confidence' in w and 'stability' in w and
            ('set back' in w or 'setback' in w or 'set it back' in w))

def behavioural_plan_new_ok(w):
    return ('confidence' in w and 'stability' in w and 'peer' in w and
            ('set back' in w or 'setback' in w) and
            ('confidence only' in w or 'confidence alone' in w or
             'set back her confidence' in w or 'set back confidence only' in w))

def request_ok(w):
    if 'overnight' not in w:
        return False
    if not ('her care' in w or 'ms corwin' in w or 'with her' in w):
        return False
    if not (('father' in w or 'mr adler' in w) and ('present' in w or 'there' in w)):
        return False
    if ('unless ms corwin' in w or 'unless the mother' in w or
            'unless mother' in w or 'unless catherine' in w or
            'parent' in w or 'guardian' in w):
        return False
    if 'away' in w and ('permitted' in w or 'may' in w or 'ok' in w or 'even if' in w):
        return False
    if 'meeting' in w and 'care' not in w and 'overnight in' not in w:
        return False
    return True

def enclosure_ok(w):
    return 'certified' in w and 'copy' in w and 'custodial plan' in w and 'enclosed' in w

def tone_old_ok(w):
    return 'soft' in w and 'formal' in w and 'succinct' in w

def tone_new_ok(w):
    return 'firm' in w and 'formal' in w and 'brief' in w

def sender_signature_ok(w):
    return 'delphine marr' in w

def salutation_ok(w):
    return 'dear counsel' in w

def copies_ok(w):
    if any(x in w for x in ['copy: mr', 'copy: counsel', 'copy: the school', 'copy the school',
                            'copy the father', 'copy: ms', 'provided to both children',
                            'copied to', 'copy someone', 'copy the father\'s attorney']):
        return False
    return ('do not copy' in w or 'no copy' in w or 'nobody is copied' in w or
            'nobody is to be copied' in w or 'no copy line' in w)

def delivery_ok(w):
    return 'post' in w and ('counsel' in w or 'office' in w) and not ('email' in w or 'courier' in w or 'hand' in w)

def interim_contact_ok(w):
    return ('confidence' in w and 'stability' in w and 'peer' in w and
            ('together' in w or 'all three' in w or 'jointly' in w or
             'same time' in w or 'not one in isolation' in w) and
            'need only' not in w and 'only consider' not in w and 'only address' not in w)

def without_prejudice_ok(w):
    return 'without prejudice' in w and ('soft' in w or 'gentle' in w or 'conciliatory' in w) and 'firm' not in w

def verify(entry, r):
    w = r['wording'].lower()
    if entry == 'OI-201':
        return addressee_father_ok(w)
    if entry == 'CL-301':
        return addressee_mother_ok(w)
    if entry == 'OI-202':
        return rofr_ok(w)
    if entry == 'OI-203':
        return children_named_ok(w)
    if entry == 'OI-204':
        return overnight_stays_ok(w)
    if entry == 'OI-205':
        return inconsistent_accounts_ok(w)
    if entry == 'OI-206':
        return concern_old_ok(w)
    if entry == 'CL-309':
        return concern_new_ok(w)
    if entry == 'OI-207':
        return behavioural_plan_old_ok(w)
    if entry == 'CL-308':
        return behavioural_plan_new_ok(w)
    if entry in ('OI-208', 'CL-302'):
        return request_ok(w)
    if entry in ('OI-209', 'CL-303'):
        return enclosure_ok(w)
    if entry == 'OI-210':
        return tone_old_ok(w)
    if entry == 'CL-307':
        return tone_new_ok(w)
    if entry == 'OI-211':
        return sender_signature_ok(w)
    if entry == 'CL-304':
        return salutation_ok(w)
    if entry == 'CL-305':
        return copies_ok(w)
    if entry == 'CL-306':
        return delivery_ok(w)
    if entry == 'CL-310':
        return interim_contact_ok(w)
    if entry == 'CL-311':
        return without_prejudice_ok(w)
    return False

rows = list(csv.DictReader(open('/app/input/letter_lines.csv')))
out_rows = []
verdicts = {}
for r in rows:
    ge = governing_entry(r['subject'], r['cited_entry'])
    if ge == 'NONE':
        verdict = 'NOT_IN_RECORD'
    else:
        verdict = 'VERIFIED' if verify(ge, r) else 'AT_ODDS'
    out_rows.append({'line_id': r['line_id'], 'verdict': verdict, 'record_entry': ge})
